      conditions.push(`(tasks.title ILIKE $${paramIndex} OR tasks.description ILIKE $${paramIndex})`);
      values.push(`%${filters.search}%`);
      paramIndex++;
    }

    if (filters.tag) {
      joins += ` INNER JOIN task_tags tt ON tasks.id = tt.task_id INNER JOIN tags tg ON tt.tag_id = tg.id`;
      conditions.push(`LOWER(tg.name) = LOWER($${paramIndex++})`);
      values.push(filters.tag);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

    const rows = await query<any>(
      `SELECT DISTINCT tasks.* FROM tasks ${joins} ${whereClause} ORDER BY tasks.created_at DESC LIMIT $${paramIndex++} OFFSET $${paramIndex}`,
      [...values, limit, offset]
    );

    return rows.map(this.mapRowToTask);
  }

  async countByUser(userId: string, filters: TaskFilters = {}): Promise<number> {
    const conditions: string[] = ['tasks.user_id = $1'];
    const values: any[] = [userId];
    let paramIndex = 2;
    let joins = '';

    if (filters.status) {
      conditions.push(`tasks.status = $${paramIndex++}`);
      values.push(filters.status);
    }

    if (filters.priority) {
      conditions.push(`tasks.priority = $${paramIndex++}`);
      values.push(filters.priority);
    }

    if (filters.assignedTo) {
      conditions.push(`tasks.assigned_to = $${paramIndex++}`);
      values.push(filters.assignedTo);
    }

    if (filters.search) {
      conditions.push(`(tasks.title ILIKE $${paramIndex} OR tasks.description ILIKE $${paramIndex})`);
      values.push(`%${filters.search}%`);
      paramIndex++;
    }

    if (filters.tag) {
      joins += ` INNER JOIN task_tags tt ON tasks.id = tt.task_id INNER JOIN tags tg ON tt.tag_id = tg.id`;
      conditions.push(`LOWER(tg.name) = LOWER($${paramIndex++})`);
      values.push(filters.tag);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

    const result = await queryOne<{ count: string }>(
      `SELECT COUNT(DISTINCT tasks.*) as count FROM tasks ${joins} ${whereClause}`,
      values
    );

    return parseInt(result?.count || '0', 10);
  }

  async findByAssignedTo(userId: string, limit: number = 50, offset: number = 0): Promise<TaskModel[]> {
    const rows = await query<any>(
      'SELECT * FROM tasks WHERE assigned_to = $1 ORDER BY created_at DESC LIMIT $2 OFFSET $3',
      [userId, limit, offset]
    );

    return rows.map(this.mapRowToTask);
  }

  async findOverdueTasks(userId: string): Promise<TaskModel[]> {
    const rows = await query<any>(
      `SELECT * FROM tasks 
       WHERE user_id = $1
       AND due_date < CURRENT_TIMESTAMP 
       AND status NOT IN ('completed', 'cancelled')
       ORDER BY due_date ASC`,
      [userId]
    );

    return rows.map(this.mapRowToTask);
  }

  async getTaskStats(userId: string): Promise<{
    total: number;
    pending: number;
    inProgress: number;
    completed: number;
    cancelled: number;
  }> {
    const result = await queryOne<any>(
      `SELECT 
         COUNT(*) as total,
         COUNT(*) FILTER (WHERE status = 'pending') as pending,
         COUNT(*) FILTER (WHERE status = 'in_progress') as "inProgress",
         COUNT(*) FILTER (WHERE status = 'completed') as completed,
         COUNT(*) FILTER (WHERE status = 'cancelled') as cancelled
       FROM tasks WHERE user_id = $1`,
      [userId]
    );

    return {
      total: parseInt(result?.total || '0', 10),
      pending: parseInt(result?.pending || '0', 10),
      inProgress: parseInt(result?.inProgress || '0', 10),
      completed: parseInt(result?.completed || '0', 10),
      cancelled: parseInt(result?.cancelled || '0', 10),
    };
  }

  private mapRowToTask(row: any): TaskModel {
    return {
      id: row.id,
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      dueDate: row.due_date ? new Date(row.due_date) : null,
      userId: row.user_id,
      assignedTo: row.assigned_to,
      createdAt: new Date(row.created_at),
      updatedAt: new Date(row.updated_at),
    };
  }
}

